d=np.load(E/'driver-model.npz');V=d['bodyRestVertices'].astype(np.float64);W=d['headWeights'];axis=d['headAxisWorld'];pivot=d['headPivotWorld'];ids=d['guideBodyVertices'];bc=d['guideBarycentrics'];F0=d['restGuideFrames'];G=d['guides'].astype(np.float64);A=d['planeNormals'];sup=d['supportVertexIds'];length=np.linalg.norm(G[:,3]-G[:,2],axis=1);rows=[]
